      pt: ["Comprimento da praia: 400 m", "Distância ao recife: 10 m", "Profundidade do recife: 30 m", "Bangalôs sobre a água: 30", "Reflorestamento de corais: 500 fragmentos/ano", "Visibilidade: 30 m"],
